const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Jianghan District, Wuhan geometry (approximate center)
  const jianghan = ee.Geometry.Point([114.27, 30.59]).buffer(5000); // 5km buffer

  // 2. Date definitions
  const date1 = '2020-01-19';
  const date2 = '2020-02-04';

  // 3. Try VIIRS Daily DNB data
  const col1 = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1/VCMCFG')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filterBounds(jianghan);

  const col2 = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V1/VCMCFG')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filterBounds(jianghan);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Jan 19 Images: ${size1}`);
  console.log(`Feb 4 Images: ${size2}`);

  // Check for missing data
  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get images and calculate stats
  const img1 = ee.Image(col1.first());
  const img2 = ee.Image(col2.first());

  const band = 'avg_rad'; // Average radiance band

  // Calculate mean nighttime light intensity for both dates
  const stats1 = img1.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: jianghan,
    scale: 500,
    maxPixels: 1e9
  });

  const stats2 = img2.select(band).reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: jianghan,
    scale: 500,
    maxPixels: 1e9
  });

  const mean1 = stats1.get('avg_rad_mean').getInfo();
  const count1 = stats1.get('avg_rad_count').getInfo();
  const mean2 = stats2.get('avg_rad_mean').getInfo();
  const count2 = stats2.get('avg_rad_count').getInfo();

  console.log(`Jan 19: Mean=${mean1}, Pixels=${count1}`);
  console.log(`Feb 4: Mean=${mean2}, Pixels=${count2}`);

  // 5. Validation
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mean1 === null || mean2 === null || isNaN(mean1) || isNaN(mean2)) {
    console.log('Calculation failed - invalid results');
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Compare and answer
  console.log(`Difference: ${(mean2 - mean1).toFixed(4)} (negative means Feb < Jan)`);

  if (mean2 < mean1) {
    console.log('Feb 4 shows lower nighttime light intensity than Jan 19');
    console.log('<answer>A</answer>');
  } else {
    console.log('Feb 4 does not show lower nighttime light intensity than Jan 19');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
